import { useEffect, useState, useCallback } from 'react'
import { useAuth } from '../../hooks/useAuth'
import { supabase } from '../../lib/supabaseClient'

type PaymentRow = {
  id: string
    order_id: string
      provider: string | null
        reference: string
          amount: number
            currency: string | null
              status: string
                paid_at: string | null
                  created_at: string
                  }

                  type OrderLite = { id: string; order_number: string }

                  const PAGE_SIZE = 25
                  const STATUS_OPTIONS = ['all', 'success', 'pending', 'mismatch', 'failed']
                  const RANGE_OPTIONS = [
                    { key: 'today', label: 'Today' },
                      { key: '7d', label: 'Last 7 days' },
                        { key: '30d', label: 'Last 30 days' },
                          { key: 'all', label: 'All time' },
                          ]

                          const STATUS_COLORS: Record<string, string> = {
                            success: '#2f855a',
                              pending: '#b7791f',
                                mismatch: '#c53030',
                                  failed: '#c53030',
                                  }

                                  function rangeStart(key: string): string | null {
                                    const d = new Date()
                                      if (key === 'today') {
                                          d.setHours(0, 0, 0, 0)
                                              return d.toISOString()
                                                }
                                                  if (key === '7d') {
                                                      d.setDate(d.getDate() - 7)
                                                          return d.toISOString()
                                                            }
                                                              if (key === '30d') {
                                                                  d.setDate(d.getDate() - 30)
                                                                      return d.toISOString()
                                                                        }
                                                                          return null
                                                                          }

                                                                          export default function Payments() {
                                                                            const { profile } = useAuth()
                                                                              const restaurantId = profile?.restaurant_id

                                                                                const [payments, setPayments] = useState<PaymentRow[]>([])
                                                                                  const [orders, setOrders] = useState<Record<string, string>>({})
                                                                                    const [status, setStatus] = useState('all')
                                                                                      const [range, setRange] = useState('7d')
                                                                                        const [search, setSearch] = useState('')
                                                                                          const [page, setPage] = useState(0)
                                                                                            const [hasMore, setHasMore] = useState(false)
                                                                                              const [loading, setLoading] = useState(true)
                                                                                                const [error, setError] = useState('')
                                                                                                  const [totalSuccess, setTotalSuccess] = useState(0)

                                                                                                    const load = useCallback(
                                                                                                        async (pageToLoad: number) => {
                                                                                                              if (!restaurantId) return
                                                                                                                    setLoading(true)
                                                                                                                          setError('')

                                                                                                                                let query = supabase
                                                                                                                                        .from('payments')
                                                                                                                                                .select('id, order_id, provider, reference, amount, currency, status, paid_at, created_at')
                                                                                                                                                        .eq('restaurant_id', restaurantId)
                                                                                                                                                                .order('created_at', { ascending: false })
                                                                                                                                                                        .range(pageToLoad * PAGE_SIZE, pageToLoad * PAGE_SIZE + PAGE_SIZE)

                                                                                                                                                                              if (status !== 'all') query = query.eq('status', status)
                                                                                                                                                                                    const start = rangeStart(range)
                                                                                                                                                                                          if (start) query = query.gte('created_at', start)
                                                                                                                                                                                                if (search.trim()) query = query.ilike('reference', `%${search.trim()}%`)

                                                                                                                                                                                                      const { data, error: err } = await query

                                                                                                                                                                                                            if (err) {
                                                                                                                                                                                                                    setError(err.message)
                                                                                                                                                                                                                            setLoading(false)
                                                                                                                                                                                                                                    return
                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                const rows = (data || []) as PaymentRow[]
                                                                                                                                                                                                                                                      setHasMore(rows.length > PAGE_SIZE)
                                                                                                                                                                                                                                                            const pageRows = rows.slice(0, PAGE_SIZE)
                                                                                                                                                                                                                                                                  setPayments((prev) => (pageToLoad === 0 ? pageRows : [...prev, ...pageRows]))

                                                                                                                                                                                                                                                                        const orderIds = pageRows.map((p) => p.order_id)
                                                                                                                                                                                                                                                                              if (orderIds.length > 0) {
                                                                                                                                                                                                                                                                                      const { data: orderRows } = await supabase
                                                                                                                                                                                                                                                                                                .from('orders')
                                                                                                                                                                                                                                                                                                          .select('id, order_number')
                                                                                                                                                                                                                                                                                                                    .in('id', orderIds)

                                                                                                                                                                                                                                                                                                                            const map: Record<string, string> = {}
                                                                                                                                                                                                                                                                                                                                    ;((orderRows || []) as OrderLite[]).forEach((o) => {
                                                                                                                                                                                                                                                                                                                                              map[o.id] = o.order_number
                                                                                                                                                                                                                                                                                                                                                      })
                                                                                                                                                                                                                                                                                                                                                              setOrders((prev) => ({ ...prev, ...map }))
                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                          setLoading(false)
                                                                                                                                                                                                                                                                                                                                                                              },
                                                                                                                                                                                                                                                                                                                                                                                  [restaurantId, status, range, search]
                                                                                                                                                                                                                                                                                                                                                                                    )

                                                                                                                                                                                                                                                                                                                                                                                      const loadTotal = useCallback(async () => {
                                                                                                                                                                                                                                                                                                                                                                                          if (!restaurantId) return
                                                                                                                                                                                                                                                                                                                                                                                              let query = supabase
                                                                                                                                                                                                                                                                                                                                                                                                    .from('payments')
                                                                                                                                                                                                                                                                                                                                                                                                          .select('amount')
                                                                                                                                                                                                                                                                                                                                                                                                                .eq('restaurant_id', restaurantId)
                                                                                                                                                                                                                                                                                                                                                                                                                      .eq('status', 'success')

                                                                                                                                                                                                                                                                                                                                                                                                                          const start = rangeStart(range)
                                                                                                                                                                                                                                                                                                                                                                                                                              if (start) query = query.gte('created_at', start)

                                                                                                                                                                                                                                                                                                                                                                                                                                  const { data } = await query
                                                                                                                                                                                                                                                                                                                                                                                                                                      const sum = (data || []).reduce((s: number, r: { amount: number }) => s + Number(r.amount), 0)
                                                                                                                                                                                                                                                                                                                                                                                                                                          setTotalSuccess(sum)
                                                                                                                                                                                                                                                                                                                                                                                                                                            }, [restaurantId, range])

                                                                                                                                                                                                                                                                                                                                                                                                                                              useEffect(() => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                  const t = setTimeout(() => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                        setPage(0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                              load(0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    loadTotal()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }, 300)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return () => clearTimeout(t)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }, [load, loadTotal])

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function loadMore() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const next = page + 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        setPage(next)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            load(next)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!restaurantId) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return <div style={{ padding: 24 }}>Loading your restaurant...</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div style={{ padding: 16 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <h2>Payments</h2>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          background: '#f7f7f7',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    padding: 12,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              borderRadius: 8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        marginBottom: 16,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  fontWeight: 700,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Total received ({RANGE_OPTIONS.find((r) => r.key === range)?.label}): ₦
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {totalSuccess.toLocaleString()}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginBottom: 16 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              type="text"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        placeholder="Search reference"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  value={search}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onChange={(e) => setSearch(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      style={{ padding: 8, flex: '1 1 160px' }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <select value={status} onChange={(e) => setStatus(e.target.value)} style={{ padding: 8 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {STATUS_OPTIONS.map((s) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <option key={s} value={s}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {s === 'all' ? 'All statuses' : s}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </select>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <select value={range} onChange={(e) => setRange(e.target.value)} style={{ padding: 8 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {RANGE_OPTIONS.map((r) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <option key={r.key} value={r.key}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {r.label}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </select>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {error && <p style={{ color: 'red' }}>{error}</p>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {payments.length === 0 && !loading && <p>No payments found for these filters.</p>}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {payments.map((p) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            key={p.id}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      style={{ border: '1px solid #ddd', borderRadius: 8, marginBottom: 10, padding: 12 }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div style={{ display: 'flex', justifyContent: 'space-between', fontWeight: 700 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span>Order #{orders[p.order_id] || '...'}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {(p.currency || 'NGN') === 'NGN' ? '₦' : p.currency + ' '}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {Number(p.amount).toLocaleString()}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div style={{ fontSize: 13, color: '#666', marginTop: 4 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {new Date(p.created_at).toLocaleString()} · {p.provider || 'unknown provider'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div style={{ fontSize: 12, color: '#666' }}>Ref: {p.reference}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div style={{ marginTop: 6, fontSize: 12 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <span
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                background: STATUS_COLORS[p.status] || '#999',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                color: '#fff',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                padding: '2px 8px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                borderRadius: 10,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                textTransform: 'uppercase',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {p.status}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ))}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {loading && <p>Loading...</p>}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {hasMore && !loading && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <button onClick={loadMore} style={{ padding: '10px 20px', width: '100%' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Load more
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              